/**
 * FolderItem Component - Displays a single folder
 * 
 * Responsibilities:
 * - Show folder name
 * - Handle folder click (navigate into)
 * - Show folder icon
 * 
 * Import rules:
 * - Can import: hooks (if needed)
 * - Can import: other components
 * - Should NOT import: services, pages
 */

import React, { useState, useRef, useEffect } from 'react';
import { formatDate } from '../../utils/helpers';

const FolderItem = ({ 
  folder, 
  onNavigate, 
  onDelete, 
  viewMode = 'list',
  isSelected = false,
  onSelect,
  onShare,
  onCopyLink,
  onRename,
  onMove,
  onCopy,
  onManageAccess
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [showContextMenu, setShowContextMenu] = useState(false);
  const contextMenuRef = useRef(null);

  const handleClick = (e) => {
    // Don't navigate if clicking on delete button
    if (e.target.closest('.folder-actions') || e.target.closest('.folder-actions-grid')) {
      return;
    }
    if (onNavigate) {
      onNavigate(folder.id, folder.name);
    }
  };

  if (viewMode === 'grid') {
    return (
      <div 
        className="folder-item folder-item-grid"
        onClick={handleClick}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <div className="folder-item-grid-content">
          <div className="folder-icon-grid">
            <svg width="48" height="48" viewBox="0 0 24 24" fill="none">
              <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="#FFA726"/>
            </svg>
            {isHovered && (
              <div className="folder-actions-grid" onClick={(e) => e.stopPropagation()}>
                {onDelete && (
                  <button 
                    className="btn-icon-grid" 
                    onClick={() => onDelete(folder.id)}
                    title="Delete"
                  >
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                      <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
                    </svg>
                  </button>
                )}
              </div>
            )}
          </div>
          <div className="folder-info-grid">
            <div className="folder-name-grid" title={folder.name}>{folder.name}</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      className="folder-item"
      onClick={handleClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="folder-icon">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
        </svg>
      </div>
      <div className="folder-name" title={folder.name}>{folder.name}</div>
      <div className="file-modified">
        {folder.updated_at || folder.created_at ? formatDate(folder.updated_at || folder.created_at) : '—'}
      </div>
      <div className="file-size">—</div>
      <div className="file-sharing">
        <span className="sharing-status">Private</span>
      </div>
      {isHovered && (
        <div className="folder-actions" onClick={(e) => e.stopPropagation()}>
          {onDelete && (
            <button 
              className="btn-icon" 
              onClick={() => onDelete(folder.id)}
              title="Delete"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
              </svg>
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default FolderItem;
